const normalizeIdentityValue = (value: unknown) => String(value ?? '').trim();

/**
 * Public identity labels must never expose the domain part of an email address.
 * Account and contact-email fields should keep using the complete email value.
 */
export const toPublicIdentityLabel = (value: unknown, fallback = '') => {
  const normalized = normalizeIdentityValue(value);
  if (!normalized) return fallback;

  const atIndex = normalized.indexOf('@');
  if (atIndex <= 0) return normalized;

  return normalized.slice(0, atIndex).trim() || fallback;
};

export const firstPublicIdentityLabel = (
  values: readonly unknown[],
  fallback = 'Wersee member',
) => {
  for (const value of values) {
    const label = toPublicIdentityLabel(value);
    if (label) return label;
  }
  return fallback;
};
